<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import DialoguePortrait from './DialoguePortrait.vue'
import CreativeIntent from './CreativeIntent.vue'
import {profile} from './people'
type Row=Record<string,any>
const props=defineProps<{project:Row;focusId?:string}>()
const emit=defineEmits(['confirm','add','prepare','generate-intent','save-intent','remove'])
const selected=ref(props.focusId||props.project.characters[0]?.id||''),editing=ref(false),removeOpen=ref(false)
const person=computed<Row|undefined>(()=>props.project.characters.find((c:Row)=>c.id===selected.value)||props.project.characters[0])
const index=computed(()=>props.project.characters.indexOf(person.value))
const box=computed(()=>props.project.annotations.find((a:Row)=>a.kind==='character'&&a.characterId===person.value?.id))
watch(()=>props.focusId,id=>{if(id)choose(id)})
watch(()=>props.project.id,()=>choose(props.project.characters[0]?.id||''))
watch(()=>props.project.characters.length,(length,old)=>{if(length>old)choose(props.project.characters[length-1].id)})
function choose(id:string){selected.value=id;editing.value=false;removeOpen.value=false}
function move(direction:number){choose(props.project.characters[index.value+direction]?.id||selected.value)}
function changed(){if(person.value)person.value.confirmed=false}
function remove(){if(person.value)emit('remove',person.value.id);removeOpen.value=false}
const kinds:Row={background:'历史背景',relationships:'人物与关系',narrative:'历史叙事'}
const evidence=computed(()=>{
 const rows:Row[]=[]
 for(const m of person.value?.mentions||[]){
  const s=props.project.sources.find((s:Row)=>s.id===m.sourceId)
  if(s?.sourceType==='creative_intent')continue
  rows.push({title:s?.title||kinds[m.kind]||'关联原文',text:s?.text||props.project.materialInputs?.[m.kind]||'',quote:m.quote||'',citation:s?.citation||'',editorialNote:s?.editorialNote||'',stale:!s||s.version!==m.sourceVersion})
 }
 if(!rows.length&&person.value?.name){
  for(const s of props.project.sources||[]){
   if(s.sourceType!=='creative_intent'&&s.text?.includes(person.value.name))rows.push({title:s.title,text:s.text,quote:person.value.name,citation:s.citation||'',editorialNote:s.editorialNote||'',stale:false})
  }
 }
 return rows.sort((a,b)=>Number(b.title.includes(person.value?.name||'∅'))-Number(a.title.includes(person.value?.name||'∅')))
})
const dialog=ref<HTMLDialogElement|null>(null),sourceIndex=ref(0),sourceBody=ref<HTMLElement|null>(null)
const activeSource=computed<Row|undefined>(()=>evidence.value[sourceIndex.value])
function openSource(source:Row){sourceIndex.value=Math.max(0,evidence.value.indexOf(source));dialog.value?.showModal()}
function switchSource(direction:number){sourceIndex.value=Math.max(0,Math.min(evidence.value.length-1,sourceIndex.value+direction));if(sourceBody.value)sourceBody.value.scrollTop=0}
const sourceLinks=computed(()=>Array.from(new Set<string>((String(activeSource.value?.citation||'')+' '+String(activeSource.value?.text||'')).match(/https?:\/\/[^\s<>"'）)\]，。；]+/g)||[])))
const excerpt=computed(()=>{const s=activeSource.value;if(!s?.quote||!s.text.includes(s.quote))return null;const start=s.text.indexOf(s.quote);return {before:s.text.slice(0,start),quote:s.quote,after:s.text.slice(start+s.quote.length)}})
</script>

<template>
<section class="character-workspace">
  <div class="character-heading"><div><small>CHARACTER NOTES</small><h2>识得画中人</h2><p>读人物、看原文，为故事留下可信的起点。</p></div><div class="actions"><button @click="emit('add')">＋ 添加人物</button><button @click="emit('prepare')">补全空白资料</button></div></div>
  <div v-if="person" class="character-book">
    <div class="character-roster" aria-label="选择人物"><button v-for="c in project.characters" :key="c.id" :aria-pressed="person.id===c.id" :class="{selected:person.id===c.id}" @click="choose(c.id)"><span :class="{confirmed:c.confirmed}" aria-hidden="true"/>{{c.name}}</button></div>
    <div class="character-spread" :id="'character-'+person.id">
      <div class="character-art"><span class="art-caption">画 中 人 物</span><DialoguePortrait v-if="box&&project.image" :key="person.id" :url="project.image" :box="box" :label="person.name+'的原画立绘'" soft/><div v-else class="portrait-missing"><span>{{person.name?.slice(0,1)||'人'}}</span><p>尚未关联画中形象</p><small>可在画作探索中关联人物标注</small></div><div class="portrait-credit">{{box?'立绘取自当前古画':'人物档案'}}<span>{{String(index+1).padStart(2,'0')}}</span></div></div>
      <div class="character-copy">
        <div class="character-meta"><span :class="{done:person.confirmed}">{{person.confirmed?'已核对':'待核对'}}</span><span>人物 {{String(index+1).padStart(2,'0')}} / {{String(project.characters.length).padStart(2,'0')}}</span></div>
        <template v-if="!editing"><h3>{{person.name}}</h3><p class="character-identity">{{person.identity||'身份尚待补充'}}</p><div class="character-description"><h4>人物小传</h4><p>{{profile(person)}}</p><details v-if="person.biography&&person.biography!==person.summary" class="biography-more"><summary>阅读完整生平</summary><p>{{person.biography}}</p></details><h4>人物关系</h4><p>{{person.relationships||'资料尚未提供人物关系。'}}</p></div></template>
        <div v-else class="character-editor"><label>姓名或称谓<input v-model="person.name" @input="changed"></label><label>身份<input v-model="person.identity" @input="changed"></label><label>人物简介<textarea v-model="person.summary" rows="2" @input="changed"/></label><label>生平经历<textarea v-model="person.biography" rows="3" @input="changed"/></label><label>人物关系<textarea v-model="person.relationships" rows="2" @input="changed"/></label></div>
        <div class="character-sources"><h4>原文依据</h4><a v-for="(s,i) in evidence.slice(0,2)" :key="i" href="#character-source" @click.prevent="openSource(s)">{{s.title}}{{evidence.filter(e=>e.title===s.title).length>1?' · '+(i+1):''}} <span>↗</span></a><a v-if="evidence.length>2" href="#character-source" @click.prevent="openSource(evidence[0])">全部 {{evidence.length}} 份资料 →</a><p v-if="!evidence.length" class="no-source">尚无关联原文</p></div>
        <div class="character-controls"><button class="primary" :disabled="person.confirmed" @click="editing=false;emit('confirm',person)">{{person.confirmed?'资料已核对':'确认此人物资料'}}</button><button class="edit-character" @click="editing=!editing">{{editing?'完成编辑':'修改资料'}}</button><button v-if="editing" class="delete-character" @click="removeOpen=!removeOpen">删除人物</button></div><div v-if="removeOpen" class="remove-character">确定删除「{{person.name}}」？<button @click="remove">确定删除</button><button @click="removeOpen=false">取消</button></div>
      </div>
    </div>
    <div class="character-pagination"><button :disabled="index===0" @click="move(-1)">← 上一位</button><span>{{person.name}}</span><button :disabled="index===project.characters.length-1" @click="move(1)">下一位 →</button></div>
  </div>
  <div v-else class="empty"><h3>从一位画中人开始</h3><p>添加人物，或补全资料后查看人物卡。</p></div>
  <CreativeIntent :project="project" @generate="emit('generate-intent',$event)" @save="emit('save-intent')"/>
  <dialog ref="dialog" class="character-source-dialog" aria-labelledby="character-source-title" @click="($event.target===dialog)&&dialog?.close()"><div v-if="activeSource"><div class="source-dialog-heading"><div><small>原文依据</small><h3 id="character-source-title" aria-live="polite">{{activeSource.title}}</h3></div><button aria-label="关闭原文" @click="dialog?.close()">×</button></div><div v-if="evidence.length>1" class="source-navigation" aria-label="切换原文资料"><button :disabled="sourceIndex===0" @click="switchSource(-1)">← 上一份</button><span aria-live="polite">{{sourceIndex+1}} / {{evidence.length}}</span><button :disabled="sourceIndex===evidence.length-1" @click="switchSource(1)">下一份 →</button></div><p v-if="activeSource.stale" class="source-stale">关联来源已变更或缺失，请结合当前原文重新核对。</p><div ref="sourceBody" class="source-dialog-body"><p v-if="excerpt" class="source-fulltext">{{excerpt.before}}<mark>{{excerpt.quote}}</mark>{{excerpt.after}}</p><template v-else><blockquote v-if="activeSource.quote">{{activeSource.quote}}</blockquote><p class="source-fulltext">{{activeSource.text||'尚无可显示的完整原文。'}}</p></template></div><div class="source-citation"><p v-if="activeSource.editorialNote">{{activeSource.editorialNote}}</p><p>{{activeSource.citation||'项目资料未填写外部出处'}}</p><a v-for="url in sourceLinks" :key="url" :href="url" target="_blank" rel="noopener noreferrer">打开原始出处 ↗</a></div></div></dialog>
</section>
</template>

<style scoped>
