:15px}.portrait-credit{left:15px;right:15px}.portrait-credit span{display:none}.portrait-missing>span{width:80px;line-height:80px;font-size:40px}.portrait-missing small{display:none}.character-copy h3{font-size:30px}.direction-fields{grid-template-columns:1fr}}@media(max-width:540px){.character-spread{grid-template-columns:1fr}.character-art{min-height:260px;padding:25px 60px}.character-art :deep(canvas){height:240px}.character-copy{padding:24px}.portrait-credit{bottom:13px}.character-heading{flex-direction:column;gap:15px}.character-heading .actions{max-width:none}.story-direction summary span{display:none}.character-roster{padding:10px}.character-pagination{padding:10px}}
.biography-more{margin-top:15px;font-size:12px;color:#748269}.biography-more summary{cursor:pointer}.biography-more p{margin-top:12px}.source-navigation{display:flex;justify-content:space-between;align-items:center;padding:12px 26px;border-bottom:1px solid #e8ebdf}.source-navigation button{border:0;background:transparent;padding:6px 0;font-size:12px}.source-navigation button:disabled{cursor:default;opacity:.35}.source-navigation span{font-size:11px;color:#829078;font-variant-numeric:tabular-nums}</style>
